bsp;&nbsp;&nbsp;<span class="sql-variable">@COLUMNS_USED</span> = columns_used_var ;<br/>&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-reserved">SET</span><br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-variable">@MULTIDB_QUERY</span> = <span class="sql-keyword">CONCAT</span>(<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-string">'SELECT "$MULTIDB" FROM `$MULTIDB`.'</span>,<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-variable">@TABLE_NAME</span>,<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-variable">@WHERE_TEXT</span><br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;) ;<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-comment">-- EXECUTION --</span><br/>&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-reserved">CREATE</span> <span class="sql-keyword">TEMPORARY</span> <span class="sql-reserved">TABLE</span> <span class="sql-variable">`MULTIDB_TEMP_DB_TBL_COLS`</span> <span class="sql-reserved">AS</span> <span class="sql-reserved">SELECT</span><br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;*<br/>&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-reserved">FROM</span><br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-reserved">SELECT</span><br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;TABLE_SCHEMA,<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-keyword">TABLE_NAME</span>,<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-keyword">COLUMN_NAME</span><br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-reserved">FROM</span><br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;INFORMATION_SCHEMA.COLUMNS<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-reserved">WHERE</span><br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;TABLE_SCHEMA <span class="sql-reserved">NOT IN</span>(<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-string">'mysql'</span>,<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-string">'test'</span>,<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-string">'tmp'</span>,<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-string">'information_schema'</span>,<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-string">'sys'</span>,<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-string">'performance_schema'</span><br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;) <span class="sql-reserved">AND</span> <span class="sql-keyword">TABLE_NAME</span> = <span class="sql-variable">@TABLE_NAME</span> <span class="sql-reserved">AND</span> <span class="sql-keyword">FIND_IN_SET</span>(<span class="sql-keyword">COLUMN_NAME</span>, <span class="sql-variable">@COLUMNS_USED</span>)<br/>&nbsp;&nbsp;&nbsp;&nbsp;) tbl<br/><span class="sql-reserved">GROUP BY</span><br/>&nbsp;&nbsp;&nbsp;&nbsp;TABLE_SCHEMA,<br/>&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-keyword">TABLE_NAME</span> ;<br/><span class="sql-reserved">SELECT</span><br/>&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-keyword">GROUP_CONCAT</span>(<br/>&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-reserved">REPLACE</span><br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-variable">@MULTIDB_QUERY</span>,<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-string">'$MULTIDB'</span>,<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-keyword">CONCAT</span>(<span class="sql-string">''</span>, TABLE_SCHEMA, <span class="sql-string">''</span>)<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;) <span class="sql-reserved">SEPARATOR</span> <span class="sql-string">"\nUNION ALL\n"</span><br/>)<br/><span class="sql-reserved">INTO</span> <span class="sql-variable">@stmt_sql</span><br/><span class="sql-reserved">FROM</span><br/>&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-variable">`MULTIDB_TEMP_DB_TBL_COLS`</span> ;<br/><span class="sql-keyword">PREPARE</span><br/>&nbsp;&nbsp;&nbsp;&nbsp;stmt<br/><span class="sql-reserved">FROM</span><br/>&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-variable">@stmt_sql</span> ;<br/><span class="sql-keyword">EXECUTE</span><br/>&nbsp;&nbsp;&nbsp;&nbsp;stmt ;<br/><span class="sql-keyword">DEALLOCATE</span><br/><span class="sql-keyword">PREPARE</span><br/>&nbsp;&nbsp;&nbsp;&nbsp;stmt ; END $$<br/>&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-comment">--
