an> <span class="sql-keyword">DEFINER</span> = <span class="sql-variable">`user`@`localhost`</span> <span class="sql-keyword">FUNCTION</span> <span class="sql-variable">`split`</span>(<span class="sql-variable">`string`</span> <span class="sql-keyword">TEXT</span>, <span class="sql-variable">`delim`</span> <span class="sql-keyword">TEXT</span>, <span class="sql-variable">`n`</span> <span class="sql-reserved">INT</span>) <span class="sql-keyword">RETURNS</span> <span class="sql-keyword">TEXT</span> <span class="sql-keyword">CHARSET</span> utf8mb4 <span class="sql-reserved">COLLATE</span> utf8mb4_unicode_520_ci <span class="sql-reserved">DETERMINISTIC</span> <span class="sql-reserved">SQL SECURITY</span> <span class="sql-keyword">INVOKER</span> <span class="sql-reserved">RETURN</span> <span class="sql-reserved">IF</span>(<br/>&nbsp;&nbsp;&nbsp;&nbsp;(<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-keyword">LENGTH</span>(<span class="sql-keyword">STRING</span>) - <span class="sql-keyword">LENGTH</span>(<span class="sql-reserved">REPLACE</span><br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(<span class="sql-keyword">STRING</span>, delim, <span class="sql-string">''</span>))<br/>&nbsp;&nbsp;&nbsp;&nbsp;) / <span class="sql-keyword">LENGTH</span>(delim) &lt; n - <span class="sql-number">1</span>,<br/>&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-reserved">NULL</span>,<br/>&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-keyword">SUBSTRING_INDEX</span>(<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-keyword">SUBSTRING_INDEX</span>(<span class="sql-keyword">STRING</span>, delim, n),<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;delim,<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-number">-1</span><br/>&nbsp;&nbsp;&nbsp;&nbsp;)<br/>) $$<br/>DELIMITER<br/>&nbsp;&nbsp;&nbsp;&nbsp;$$<br/><span class="sql-reserved">CREATE</span> <span class="sql-keyword">DEFINER</span> = <span class="sql-variable">`root`@`localhost`</span> <span class="sql-keyword">FUNCTION</span> <span class="sql-variable">`substrCount`</span>(<br/>&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-variable">`s`</span> <span class="sql-reserved">VARCHAR</span>(<span class="sql-number">255</span>),<br/>&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-variable">`ss`</span> <span class="sql-reserved">VARCHAR</span>(<span class="sql-number">255</span>)<br/>) <span class="sql-keyword">RETURNS</span> <span class="sql-reserved">TINYINT</span>(<span class="sql-number">3</span>) <span class="sql-reserved">UNSIGNED</span> <span class="sql-reserved">DETERMINISTIC</span> <span class="sql-reserved">READS SQL DATA</span> <span class="sql-reserved">SQL SECURITY</span> <span class="sql-keyword">INVOKER</span> <span class="sql-keyword">BEGIN</span><br/>&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-reserved">DECLARE</span><br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-keyword">COUNT</span> <span class="sql-reserved">TINYINT</span>(<span class="sql-number">3</span>) <span class="sql-reserved">UNSIGNED</span> ; <span class="sql-reserved">DECLARE</span> OFFSET_I <span class="sql-reserved">TINYINT</span>(<span class="sql-number">3</span>) <span class="sql-reserved">UNSIGNED</span> ; <span class="sql-reserved">DECLARE</span> <span class="sql-reserved">CONTINUE</span><br/>&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-keyword">HANDLER</span> <span class="sql-reserved">FOR</span> <span class="sql-reserved">SQLSTATE</span><br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-string">'02000'</span><br/>&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-reserved">SET</span><br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;s = <span class="sql-reserved">NULL</span> ;<br/>&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-reserved">SET</span><br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-keyword">COUNT</span> = <span class="sql-number">0</span> ;<br/>&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-reserved">SET</span><br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;OFFSET_I = <span class="sql-number">1</span> ; <span class="sql-reserved">REPEAT</span> <span class="sql-reserved">IF</span> <span class="sql-reserved">NOT</span> <span class="sql-keyword">ISNULL</span>(s) <span class="sql-reserved">AND</span> OFFSET_I &gt; <span class="sql-number">0</span> <span class="sql-reserved">THEN</span><br/>&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-reserved">SET</span><br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;OFFSET_I = <span class="sql-keyword">LOCATE</span>(ss, s, OFFSET_I) ; <span class="sql-reserved">IF</span> OFFSET_I &gt; <span class="sql-number">0</span> <span class="sql-reserved">THEN</span><br/>&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-reserved">SET</span><br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-keyword">COUNT</span> = <span class="sql-keyword">COUNT</span> + <span class="sql-number">1</span> ;<br/>&nbsp;&nbsp;&nbsp;&nbsp;<span class="sql-reserved">SET</span><br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;OFFSET_I = OFFSET_I + <span class="sql-number">1</span> ;<br/><span class="sql-keyword">END</span> <span class="sql-reserved">IF</span> ;<br/><span class="sql-keyword">END</span> <span class="sql-reserved">IF</span> ; <span class="sql-keyword">UNTIL</span> <span class="sql-keyword">ISNULL</span>(s) <span class="sql-reserved">OR</span> OFFSET_I = <span class="sql-number">0</span><br/><span class="sql-keyword">END</span> <span class="sql-reserved">REPEAT</span> ; <span class="sql-reserved">RETURN</span> <span class="sql-keyword">COUNT</span> ; END $$<br/>DELIMITER<br/>&nbsp;&nbsp;&nbsp;&nbsp;;

